import logging
import warnings
from taf.transport.ssh.connection import ProxySSHConnection, SSHConnection
from taf.internal.managedobject import ManagedObject

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ManagedSshConnection(ManagedObject):
    """
    ManagedObject interface for SSHConnection/ProxySSHConnection.

    - Create SSHConnection or ProxySSHConnection as delegate depending on the presence of a proxy.
    - Configure the delegate in constructor.
    - Map setup()/teardown() to connect()/disconnect().
    - Log setup/teardown.
    """

    def __init__(
            self,
            host,
            user,
            password,
            port=None,
            proxy=None,
            **kwargs):
        """
        Create an SshConnection.

        :param str host: host or IP hostess
        :param str user: user name
        :param str password: password
        :param int port: port
        :param ManagedSSHConnection proxy: underlying SSH connection to intermediate host
        """
        warnings.warn('This library is deprecated, use "taf.internal.execution.ssh" instead.',
                      FutureWarning,
                      stacklevel=2)
        super(ManagedSshConnection, self).__init__(**kwargs)
        default_params = {'hostname': host,
                          'port': port,
                          'username': user,
                          'password': password}
        params = {
            k: v
            for k, v in default_params.items()
            if v is not None}
        self._host = host
        self._port = port
        self._user = user
        self._password = password
        self._proxy = proxy
        if proxy is not None:
            self.add_prerequisite(proxy)
            params["proxy"] = proxy.ssh_connection
        self._ssh_connection = self._create_ssh_connection()
        self._ssh_connection.configure(**params)

    @property
    def ssh_connection(self):
        return self._ssh_connection

    @property
    def user(self):
        return self._ssh_connection.params["username"]

    @property
    def host(self):
        return self._ssh_connection.params["hostname"]

    def _create_ssh_connection(self):
        if self._proxy:
            return ProxySSHConnection()
        else:
            return SSHConnection()

    def __getattr__(self, name):
        if name in self._ssh_connection.params:
            return self._ssh_connection.params[name]
        else:
            return getattr(self._ssh_connection, name)

    def _setup(self):
        logger.debug("connecting to {host!r}:{port!r} as {user!r}:{password!r}".format(
            host=self._host,
            port=self._port,
            user=self._user,
            password=self._password))
        self._ssh_connection.connect()

    def _teardown(self):
        logger.debug("disconnecting from {host!r}:{port!r} as {user!r}".format(
            host=self._host,
            port=self._port,
            user=self._user))
        self._ssh_connection.disconnect()
